Comment:
Two channels. Mono spreads to both sides at −3 dB, as libswresample's
rematrix does (rematrix.c, `center_mix_level`), which the mix was balanced
with; stereo passes through; more channels keep their first two.

Code it sits on:
export const toStereo = (pcm: Pcm): Pcm => {
  const [first, second] = pcm.channels;
  if (first === undefined) return silence(pcm.rate, pcm.frames, 2);
  if (second !== undefined) return { ...pcm, channels: [first, second] };
  const side = first.map((x) => x * Math.SQRT1_2);
  return { ...pcm, channels: [side, side.slice()] };
};

Comment:
Interleaved 16-bit samples, converted as libswresample does
(audioconvert.c: `av_clip_int16(lrint(x * (1 << 15)))`).

Code it sits on:
export const toInt16 = (pcm: Pcm): Int16Array => {
  const n = pcm.channels.length;
  const out = new Int16Array(pcm.frames * n);
  for (const [c, channel] of pcm.channels.entries())
    for (let i = 0; i < pcm.frames; i++)
      out[i * n + c] = Math.max(-32768, Math.min(32767, lrint((channel[i] ?? 0) * 32768)));
  return out;
};

Comment:
A change's id: its kind and origin hashed to 64 bits (two FNV-1a passes), in hex. Pure.

Code it sits on:
const changeId = (kind: string, origin: string): string => {
  const text = `${kind} ${origin}`;
  const half = (start: number) => (fnvText(start, text) >>> 0).toString(16).padStart(8, '0');
  return `${half(FNV_START)}${half(FNV_SECOND)}`;
};

Comment:
The 4 allpasses in series for one frame (feedback 0.5); their places follow the combs' in `at`.

Code it sits on:
const allpasses = (lines: RoomLines, at: Int32Array, input: number) => {
  let acc = input;
  for (let a = 0; a < lines.allpasses.length; a++) {
    const line = lines.allpasses[a];
    if (line === undefined) continue;
    const k = at[lines.combs.length + a] ?? 0;
    const back = line[k] ?? 0;
    line[k] = acc + back * 0.5;
    acc = back - acc;
    at[lines.combs.length + a] = (k + 1) % line.length;
  }
  return acc;
};

Comment:
Film `film`'s take of the beat `read` lists: the attempt `attempt` names
when it names one, else the one kept, else the staging take the timings
name; none when there is none of these.

Code it sits on:
export const takeHeard = (
  film: string,
  read: StudioAttempts,
  attempt: Option.Option<string>,
): Option.Option<TakeHeard> =>
  Option.match(attempt, {
    onSome: (file) =>
      Option.map(
        Arr.findFirst(read.attempts, (a) => a.file === file),
        (a): TakeHeard => ({
          url: attemptUrl(film, read.beat, a.file),
          source: 'recorded',
          heard: Option.some(a.transcript),
          duration: a.duration,
        }),
      ),
    onNone: () =>
      Option.orElse(
        Option.map(
          Arr.findFirst(read.attempts, (a) => a.kept),
          (a): TakeHeard => ({
            url: attemptUrl(film, read.beat, a.file),
            source: 'recorded',
            heard: Option.some(a.transcript),
            duration: a.duration,
          }),
        ),
        () =>
          Option.map(Option.fromUndefinedOr(read.staged), (s): TakeHeard => ({
            url: narrationFileUrl(film, s.file),
            source: 'staging',
            heard: Option.none(),
            duration: s.duration,
          })),
      ),
  });

